def register_legacy_targets(apps, schema_editor):
    """仅保留已保存的目录归属，不访问 SVN 或修改任务。"""
    task_model = apps.get_model("package", "PackageTask")
    namespace_model = apps.get_model("package", "PackageSvnNamespace")
    target_model = apps.get_model("package", "PackageSvnTarget")
    alias = schema_editor.connection.alias
    rows = (
        task_model.objects.using(alias).filter(stage_info__svn_push__remote_url__isnull=False)
        .values_list("project_id", "stage_info").iterator()
    )
    for project_id, stage_info in rows:
        url = stage_info["svn_push"]["remote_url"]
        if not isinstance(url, str):
            continue
        try:
            server, path = svn_target(url)
        except ValueError:
            continue
        namespace_model.objects.using(alias).get_or_create(pk=server)
        target_model.objects.using(alias).get_or_create(
            namespace_id=server, path_key=sha256(path.encode()).hexdigest(), project_id=project_id,
            defaults={"path": path},
        )


